INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000001f',1,'APPROVED','PUBLISHED',
'{"objectives":["Use all major question words in Hindi at A1","Form correct questions in Hindi","Understand and answer basic questions"],"explanation":{"intro":"Question words vocabulary covers all major Hindi interrogative words and how to form correct questions at A1.","culturalNote":"प्रश्न शब्द — Question Words: Hindi question words: क्या (kya = what/yes-no marker), कौन (kaun = who), कहाँ (kahaan = where), कब (kab = when), क्यों (kyun = why), कैसे (kaise = how), कितना (kitna = how much/many), कौन सा/सी (kaun sa/si = which). Key: क्या has double duty — (1) yes/no question marker: क्या आप ठीक हैं? (Are you fine?); (2) what: यह क्या है? (What is this?). Question word position: Hindi question words go in the position of the expected answer (not at the beginning like English wh-movement). Example: आप कहाँ रहते हैं? (Where do you live? — same position as the answer: दिल्ली में). Cultural: Indians often answer yes/no questions with the verb repeated rather than हाँ/नहीं: क्या आप खाएँगे? → खाऊँगा (I will eat — not ''yes''). Head wobble (sideways) can mean yes, agreement, or ''I''m listening.''"},"examples":[{"hindi":"आप कहाँ से हैं?","transliteration":"Aap kahaan se hain?","english":"Where are you from?"},{"hindi":"यह क्या है? यह एक किताब है।","transliteration":"Yah kya hai? Yah ek kitaab hai.","english":"What is this? This is a book."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can use all major Hindi question words and form correct questions."}}',
'{"items":[{"word":"क्या","translation":"what / (yes/no marker)","transliteration":"kya","pronunciation":"kya","example":"यह क्या है?"},{"word":"कौन","translation":"who","transliteration":"kaun","pronunciation":"kaun","example":"वह कौन है?"},{"word":"कहाँ","translation":"where","transliteration":"kahaan","pronunciation":"ka-HAAN","example":"आप कहाँ हैं?"},{"word":"कब","translation":"when","transliteration":"kab","pronunciation":"kab","example":"वह कब आएगा?"},{"word":"क्यों","translation":"why","transliteration":"kyun","pronunciation":"kyun","example":"आप क्यों आए?"},{"word":"कैसे","translation":"how","transliteration":"kaise","pronunciation":"KAI-se","example":"आप कैसे हैं?"}]}',
'{"title":"क्या + sentence = Yes/No question (क्या as yes/no marker)","pattern":"क्या + declarative sentence = yes/no question. क्या आप ठीक हैं? = Are you fine? (no word change except adding क्या at start). In English, yes/no questions invert subject-verb; in Hindi, क्या is placed at the beginning of an otherwise normal declarative sentence — the SOV word order does NOT change.","explanation":"Hindi yes/no questions: add क्या at the start of the sentence (or raise intonation — spoken Hindi often uses intonation alone). No subject-verb inversion. क्या आप दिल्ली से हैं? = Are you from Delhi? (literally: What you Delhi from are?). Answer: हाँ, मैं दिल्ली से हूँ (Yes, I am from Delhi) or नहीं, मैं मुंबई से हूँ (No, I am from Mumbai). Note: क्या at sentence start = yes/no question. क्या after subject/in middle = ''what'': यह क्या है? (What is this?).","examples":[{"sentence":"क्या आप हिंदी बोलते हैं?","transliteration":"Kya aap Hindi bolte hain?","translation":"Do you speak Hindi?"},{"sentence":"क्या आज स्कूल है?","transliteration":"Kya aaj school hai?","translation":"Is there school today?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"क्यों means?","options":["why","where","when","how"],"correctAnswer":"why"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Where are you from?","options":["आप कहाँ से हैं?","आप कहाँ हैं?","आप कब से हैं?","वह कहाँ से है?"],"correctAnswer":"आप कहाँ से हैं?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"___ आप हिंदी बोलते हैं?","options":["क्या","कैसे","कब","क्यों"],"correctAnswer":"क्या"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Do you speak Hindi?","wordBankItems":["क्या","आप","हिंदी","बोलते","हैं","?"],"correctAnswer":"क्या आप हिंदी बोलते हैं ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"कौन means?","options":["who","what","which","where"],"correctAnswer":"who"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000020',1,'APPROVED','PUBLISHED',
'{"objectives":["Name professions and jobs in Hindi at A1","Describe what someone does for a living","Use है/हैं with profession nouns"],"explanation":{"intro":"Professions vocabulary covers common jobs and how to describe what someone does for a living in Hindi at A1.","culturalNote":"पेशे और काम — Professions: पेशा (pesha) = profession. डॉक्टर (doctor). इंजीनियर (engineer). शिक्षक/शिक्षिका (shikshak/shikhshika = teacher — male/female). किसान (kisaan = farmer). दुकानदार (dukaandaar = shopkeeper). नेता (neta = politician/leader). पुलिसवाला/पुलिसवाली (policewala/policewali = policeman/woman). नर्स (nurse). मजदूर (mazdoor = labourer). कारीगर (kaareegar = craftsman/artisan). Key: वह X हैं (vah X hain = he/she is X — hain used for respect even for singular). Cultural: Doctor, engineer and lawyer are still highly prestigious career choices. IIT (engineering) and IIM (management) — top institutions. Civil services (IAS, IPS) — extremely competitive — among the most prestigious careers. Key social context: caste and occupation historically linked (Brahmin = scholars, Kshatriya = warriors, Vaishya = merchants, Shudra = labourers) — modernising but persists in some contexts. Reservation system for SC/ST/OBC in government jobs."},"examples":[{"hindi":"मेरे पिताजी डॉक्टर हैं।","transliteration":"Mere pitaji doctor hain.","english":"My father is a doctor."},{"hindi":"वह एक अच्छी शिक्षिका हैं।","transliteration":"Vah ek acchi shikshika hain.","english":"She is a good teacher."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name professions in Hindi and describe what someone does for a living."}}',
'{"items":[{"word":"पेशा","translation":"profession","transliteration":"pesha","pronunciation":"PE-sha","example":"आपका पेशा?"},{"word":"डॉक्टर","translation":"doctor","transliteration":"doctor","pronunciation":"DOK-tor","example":"डॉक्टर हैं।"},{"word":"शिक्षक/शिक्षिका","translation":"teacher (m/f)","transliteration":"shikshak/shikhshika","pronunciation":"SHIK-shak/shik-SHI-ka","example":"अच्छी शिक्षिका।"},{"word":"किसान","translation":"farmer","transliteration":"kisaan","pronunciation":"ki-SAAN","example":"किसान काम करता है।"},{"word":"इंजीनियर","translation":"engineer","transliteration":"engineer","pronunciation":"in-ji-NEER","example":"सॉफ्टवेयर इंजीनियर।"},{"word":"नेता","translation":"politician/leader","transliteration":"neta","pronunciation":"NE-ta","example":"राजनीतिक नेता।"}]}',
'{"title":"वह X हैं — He/she is X (हैं used for respectful singular)","pattern":"वह X हैं (honorific/respectful) = He/she is X. हैं is grammatically plural but used as respectful singular in Hindi — the ''आप-equivalent'' third person. Contrast: वह X है (vah X hai = he/she is X — neutral/informal third person). Using हैं with वह = showing respect to the person being referred to. Common for: teachers, parents, elders, respected figures.","explanation":"Respect/honor (izzat) in Hindi grammar: Hindi has three levels of address/reference — तू (very familiar/intimate), तुम (familiar), आप (formal/respectful). For third persons: वह X है (neutral) vs. वह X हैं (respectful). Use हैं (plural form) as honorific singular for respected individuals. Example: आपके पिताजी क्या करते हैं? (What does your father do? — respectful). मेरे पिताजी डॉक्टर हैं (My father is a doctor — hain = respectful). This grammatical politeness is deeply embedded in Hindi/Indian culture.","examples":[{"sentence":"वे बहुत अच्छे इंजीनियर हैं।","transliteration":"Ve bahut achche engineer hain.","translation":"He/she is a very good engineer."},{"sentence":"हमारे प्रधानमंत्री कौन हैं?","transliteration":"Hamaare pradhanmantri kaun hain?","translation":"Who is our Prime Minister?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"किसान means?","options":["farmer","labourer","craftsman","trader"],"correctAnswer":"farmer"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My father is a doctor.","options":["मेरे पिताजी डॉक्टर हैं।","मेरी माँ डॉक्टर हैं।","मेरे पिताजी इंजीनियर हैं।","मेरे पिताजी डॉक्टर है।"],"correctAnswer":"मेरे पिताजी डॉक्टर हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वे बहुत अच्छे इंजीनियर ___ ।","options":["हैं","है","हो","हूँ"],"correctAnswer":"हैं"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She is a good teacher.","wordBankItems":["वह","एक","अच्छी","शिक्षिका","हैं","।"],"correctAnswer":"वह एक अच्छी शिक्षिका हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"पेशा means?","options":["profession","work","salary","office"],"correctAnswer":"profession"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000021',1,'APPROVED','PUBLISHED',
'{"objectives":["Name natural features and outdoor settings in Hindi at A1","Use location postpositions with nature vocabulary","Describe natural scenery"],"explanation":{"intro":"Nature vocabulary covers mountains, rivers, forests, and outdoor settings and how to describe them in Hindi at A1.","culturalNote":"प्रकृति — Nature: प्रकृति (prakriti) = nature (Sanskrit — also: Prakriti = primordial nature in Samkhya philosophy). पहाड़ (pahad) = mountain. नदी (nadi) = river — feminine. जंगल (jangal) = forest (from Persian). समुद्र (samudra) = sea/ocean. आकाश (aakaash) = sky. धरती (dharti) = earth/ground. पेड़ (ped) = tree. फूल (phool) = flower. Key rivers: गंगा (Ganga/Ganges — most sacred — Hinduism), यमुना (Yamuna — Delhi), ब्रह्मपुत्र (Brahmaputra), कृष्णा (Krishna), कावेरी (Kaveri). Himalayas (हिमालय = himaalaya = abode of snow). Key wildlife: Project Tiger (बाघ संरक्षण), elephant corridor. India''s extraordinary biodiversity: Western Ghats, Sundarbans mangroves, Thar Desert, Himalayan alpine zones. Sacred geography: India has sacred rivers, mountains, forests. गंगा माँ (Ganga Maa = Mother Ganges). सुंदरवन (Sundarbans = beautiful forest)."},"examples":[{"hindi":"हिमालय भारत के उत्तर में है।","transliteration":"Himalaya Bharat ke uttar mein hai.","english":"The Himalayas are in the north of India."},{"hindi":"जंगल में बहुत सुंदर पेड़ और फूल हैं।","transliteration":"Jangal mein bahut sundar ped aur phool hain.","english":"In the forest there are many beautiful trees and flowers."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name natural features in Hindi and describe outdoor settings."}}',
'{"items":[{"word":"पहाड़","translation":"mountain","transliteration":"pahad","pronunciation":"pa-HAD","example":"ऊँचा पहाड़।"},{"word":"नदी","translation":"river","transliteration":"nadi","pronunciation":"na-DEE","example":"नदी बहती है।"},{"word":"जंगल","translation":"forest","transliteration":"jangal","pronunciation":"JAN-gal","example":"घना जंगल।"},{"word":"पेड़","translation":"tree","transliteration":"ped","pronunciation":"ped","example":"बड़ा पेड़।"},{"word":"समुद्र","translation":"sea/ocean","transliteration":"samudra","pronunciation":"sa-MUD-ra","example":"समुद्र किनारा।"},{"word":"आकाश","translation":"sky","transliteration":"aakaash","pronunciation":"aa-KAASH","example":"नीला आकाश।"}]}',
'{"title":"X के + direction/side में है — X is in the (direction) of Y (के + cardinal direction + में)","pattern":"X के Y में है = X is in the Y of Z. के = of (masculine oblique possessive before postposition). Y = direction: उत्तर में (in the north), दक्षिण में (in the south), पूर्व में (in the east), पश्चिम में (in the west). भारत के उत्तर में = in the north of India. Pattern: Z के Y-direction में = in the Y of Z.","explanation":"Directional postpositions: के उत्तर में (in the north of), के दक्षिण में (in the south of), के पूर्व में (in the east of), के पश्चिम में (in the west of). के is required before the direction postposition because the direction word takes में which requires a preceding modifier. Example: दिल्ली भारत के उत्तर में है (Delhi is in the north of India). के बीच में (in the middle of), के पास (near), के सामने (in front of), के पीछे (behind).","examples":[{"sentence":"मुंबई भारत के पश्चिम में है।","transliteration":"Mumbai Bharat ke pashchim mein hai.","translation":"Mumbai is in the west of India."},{"sentence":"सूरज आकाश में है।","transliteration":"Suraj aakaash mein hai.","translation":"The sun is in the sky."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"पहाड़ means?","options":["mountain","river","forest","desert"],"correctAnswer":"mountain"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Himalayas are in the north of India.","options":["हिमालय भारत के उत्तर में है।","हिमालय भारत के दक्षिण में है।","हिमालय भारत के पश्चिम में है।","हिमालय भारत के उत्तर पर है।"],"correctAnswer":"हिमालय भारत के उत्तर में है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मुंबई भारत के ___ में है।","options":["पश्चिम","उत्तर","पूर्व","दक्षिण"],"correctAnswer":"पश्चिम"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In the forest there are many beautiful trees and flowers.","wordBankItems":["जंगल","में","बहुत","सुंदर","पेड़","और","फूल","हैं","।"],"correctAnswer":"जंगल में बहुत सुंदर पेड़ और फूल हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"नदी means?","options":["river","lake","pond","waterfall"],"correctAnswer":"river"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000022',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about holidays and travel in Hindi at A1","Use past tense with गया/गई for trips","Describe a simple holiday"],"explanation":{"intro":"Holiday and trip vocabulary covers destinations, activities, and describing a past trip in Hindi at A1.","culturalNote":"यात्रा और छुट्टी — Holidays and Trips: छुट्टी (chhutthi) = holiday/leave/vacation (also: कार्यालय से छुट्टी = leave from office). घूमना (ghoomna) = to roam/travel/sightsee. देखना (dekhna) = to see. जाना (jaana) = to go. Past tense: गया (gaya = went — masculine), गई (gayi = went — feminine). Key tourist destinations: ताज महल (Taj Mahal — Agra — UNESCO — monument of love), राजस्थान (Rajasthan — palaces, forts, desert), गोवा (Goa — beaches), केरल (Kerala — backwaters, houseboats), हिमाचल प्रदेश (Himachal Pradesh — mountains), काशी/वाराणसी (Varanasi — holiest Hindu city — Ganges ghats). भारत में अनेक पर्यटन स्थल हैं (India has many tourist sites). Incredible India — tourism campaign. Pilgrimage tourism: Char Dham (चार धाम), Amarnath, Vaishno Devi. Summer vs. winter hill station distinction."},"examples":[{"hindi":"पिछले साल मैं ताज महल देखने गया।","transliteration":"Pichle saal main Taj Mahal dekhne gaya.","english":"Last year I went to see the Taj Mahal."},{"hindi":"हम गोवा में तीन दिन रहे।","transliteration":"Hum Goa mein teen din rahe.","english":"We stayed in Goa for three days."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about past trips and holidays in Hindi using past tense."}}',
'{"items":[{"word":"छुट्टी","translation":"holiday/vacation","transliteration":"chhutthi","pronunciation":"CHHUTT-hi","example":"गर्मी की छुट्टी।"},{"word":"घूमना","translation":"to roam/travel/sightsee","transliteration":"ghoomna","pronunciation":"GHOOM-na","example":"घूमने जाना।"},{"word":"पिछले साल","translation":"last year","transliteration":"pichle saal","pronunciation":"PICH-le saal","example":"पिछले साल गया।"},{"word":"रहना","translation":"to stay/live","transliteration":"rehna","pronunciation":"REH-na","example":"रहे हम।"},{"word":"दिन","translation":"day","transliteration":"din","pronunciation":"din","example":"तीन दिन।"},{"word":"देखने जाना","translation":"to go to see","transliteration":"dekhne jaana","pronunciation":"DEKH-ne JAA-na","example":"देखने जाना।"}]}',
'{"title":"X देखने गया/गई — went to see X (infinitive oblique + गया/गई)","pattern":"Infinitive oblique + जाना = to go in order to do (purpose). देखना (to see) → oblique: देखने (for seeing). मैं X देखने गया = I went to see X (male). मैं X देखने गई = I went to see X (female). Oblique infinitive: verb stem + ने (same form as agent-marked infinitive). Used to express purpose of going: खाने गया (went to eat), पढ़ने गया (went to study).","explanation":"Purpose construction with infinitive oblique: verb stem + ने + जाना/आना. मैं ताज महल देखने गया = I went to see the Taj Mahal (dekhne = for the purpose of seeing — oblique of dekhna). Past tense of जाना: गया (masc. sg.), गई (fem. sg.), गए (masc. pl.), गईं (fem. pl.). Note: masculine past forms don''t use हूँ/था/थी with ''go'' in simple past — just गया/गई directly (simple past perfective). Contrast: मैं गया हूँ (I have gone — perfect), मैं गया (I went — simple past).","examples":[{"sentence":"वह स्कूल पढ़ने गई।","transliteration":"Vah school padhne gayi.","translation":"She went to school to study."},{"sentence":"हम बाज़ार खरीदारी करने गए।","transliteration":"Hum baazaar kharidaari karne gaye.","translation":"We went to the market to shop."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"छुट्टी means?","options":["holiday/vacation","work","school","break"],"correctAnswer":"holiday/vacation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Last year I went to see the Taj Mahal.","options":["पिछले साल मैं ताज महल देखने गया।","इस साल मैं ताज महल देखने गया।","पिछले साल मैं ताज महल देखने गई।","पिछले साल वह ताज महल देखने गया।"],"correctAnswer":"पिछले साल मैं ताज महल देखने गया।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वह स्कूल पढ़ने ___ ।","options":["गई","गया","गए","जाती है"],"correctAnswer":"गई"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We went to the market to shop.","wordBankItems":["हम","बाज़ार","खरीदारी","करने","गए","।"],"correctAnswer":"हम बाज़ार खरीदारी करने गए ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"घूमना means?","options":["to roam/travel/sightsee","to rest","to sleep","to eat"],"correctAnswer":"to roam/travel/sightsee"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000023',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about friends and socialising in Hindi at A1","Use साथ for ''with'' in social contexts","Describe social activities and invitations"],"explanation":{"intro":"Friends and socialising vocabulary covers making plans, inviting friends, and describing social activities in Hindi at A1.","culturalNote":"मित्र और सामाजिकता — Friends and Socialising: मित्र/दोस्त (mitra/dost) = friend (mitra = Sanskrit formal; dost = Persian/Urdu informal — more common in speech). यार (yaar) = friend/buddy (informal — Persian — very common in North India). साथ (saath) = with/together. मिलना (milna) = to meet. बुलाना (bulaana) = to invite/call. पार्टी (party). घर पर (ghar par = at home). बाहर (bahar = outside). साथ-साथ (saath-saath = together). Cultural: Hospitality (आतिथ्य = aatithya) is extremely important in Indian culture — Atithi Devo Bhava (अतिथि देवो भव = the guest is god). Refusing food/drink offered by a host is considered impolite. Dropping by unannounced is quite common — doesn''t require advance notice. Tea is always offered to guests. बचपन के दोस्त (bachpan ke dost = childhood friends) — bonds of school/neighborhood lasting lifetimes. Concepts: जिगरी दोस्त (jigri dost = bosom friend — jigri = from the heart — Persian jigar = liver)."},"examples":[{"hindi":"मैं आज अपने दोस्त के साथ फ़िल्म देखने जाऊँगा।","transliteration":"Main aaj apne dost ke saath film dekhne jaunga.","english":"Today I will go to watch a film with my friend."},{"hindi":"क्या तुम कल मेरे घर आ सकते हो?","transliteration":"Kya tum kal mere ghar aa sakte ho?","english":"Can you come to my house tomorrow?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about friends and social plans in Hindi."}}',
'{"items":[{"word":"दोस्त","translation":"friend","transliteration":"dost","pronunciation":"dost","example":"मेरा दोस्त।"},{"word":"साथ","translation":"with/together","transliteration":"saath","pronunciation":"saath","example":"साथ जाना।"},{"word":"मिलना","translation":"to meet","transliteration":"milna","pronunciation":"MIL-na","example":"दोस्त से मिलना।"},{"word":"बुलाना","translation":"to invite/call","transliteration":"bulaana","pronunciation":"bu-LAA-na","example":"पार्टी में बुलाना।"},{"word":"आना","translation":"to come","transliteration":"aana","pronunciation":"AA-na","example":"घर आना।"},{"word":"अपना","translation":"own/one''s own","transliteration":"apna","pronunciation":"AP-na","example":"अपना दोस्त।"}]}',
'{"title":"X के साथ Y करना — to do Y with X (के साथ = with)","pattern":"X के साथ Y = Y with X. के साथ = with (postposition — follows the person/thing you are with). अपने दोस्त के साथ = with (my) own friend. के साथ requires the oblique form of the preceding noun (दोस्त → दोस्त, X → X ke for possessives: apne dost ke saath). Used for accompaniment: साथ alone means ''together.'' के साथ = with (specific person/thing).","explanation":"के साथ (ke saath) = with (postposition for accompaniment). के = of/''s (oblique marker — triggers oblique case on preceding noun). साथ = with, together. X के साथ = with X. अपना (apna) = own (reflexive possessive — refers back to subject: मैं अपने दोस्त के साथ = I with my own friend). Contrast: मेरे दोस्त के साथ (with my friend — external possessive) vs. अपने दोस्त के साथ (with one''s own friend — reflexive — clearer when subject is not first person). With: के साथ; without: के बिना (ke bina).","examples":[{"sentence":"वह अपनी बहन के साथ पार्क गई।","transliteration":"Vah apni bahan ke saath park gayi.","translation":"She went to the park with her sister."},{"sentence":"हम सब साथ-साथ खाना खाएँगे।","transliteration":"Hum sab saath-saath khaana khaenge.","translation":"We will all eat together."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"दोस्त means?","options":["friend","colleague","neighbor","relative"],"correctAnswer":"friend"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Today I will go to watch a film with my friend.","options":["मैं आज अपने दोस्त के साथ फ़िल्म देखने जाऊँगा।","मैं कल अपने दोस्त के साथ फ़िल्म देखने जाऊँगा।","मैं आज अपनी दोस्त के साथ फ़िल्म देखने जाऊँगा।","मैं आज अपने भाई के साथ फ़िल्म देखने जाऊँगा।"],"correctAnswer":"मैं आज अपने दोस्त के साथ फ़िल्म देखने जाऊँगा।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वह अपनी बहन ___ साथ पार्क गई।","options":["के","का","की","को"],"correctAnswer":"के"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We will all eat together.","wordBankItems":["हम","सब","साथ-साथ","खाना","खाएँगे","।"],"correctAnswer":"हम सब साथ-साथ खाना खाएँगे ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"मिलना means?","options":["to meet","to invite","to come","to go"],"correctAnswer":"to meet"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000024',1,'APPROVED','PUBLISHED',
'{"objectives":["Name languages and countries in Hindi at A1","Use X में बोलना for speaking in a language","Talk about nationality and origin"],"explanation":{"intro":"Languages and countries vocabulary covers major world languages, countries, and how to talk about nationality in Hindi at A1.","culturalNote":"भाषाएँ और देश — Languages and Countries: भाषा (bhaasha) = language. देश (desh) = country. भारत (Bharat) = India (official name — Bharat Mata = Mother India). हिंदी (Hindi) — official language of India (along with English). India has 22 scheduled languages. Key Indian languages: हिंदी, बांग्ला (Bangla = Bengali), तेलुगू (Telugu), मराठी (Marathi), तमिल (Tamil), उर्दू (Urdu), कन्नड़ (Kannada), मलयालम (Malayalam), पंजाबी (Punjabi), गुजराती (Gujarati). World languages: अंग्रेज़ी (Angrezi = English), फ़्रांसीसी (French), जर्मन (German), जापानी (Japanese), चीनी (Chinese), अरबी (Arabic), स्पेनिश (Spanish). Key: X बोलना (X bolna = to speak X language — used without ''में''). मैं हिंदी बोलता हूँ (Main Hindi bolta hoon = I speak Hindi). Nationality: X देश का/की हूँ (I am from country X). भारतीय (Bhartiya = Indian). अंग्रेज़ (Angrez = British/English person)."},"examples":[{"hindi":"मैं हिंदी और थोड़ी अंग्रेज़ी बोलता हूँ।","transliteration":"Main Hindi aur thodi angrezi bolta hoon.","english":"I speak Hindi and a little English."},{"hindi":"आप किस देश से हैं?","transliteration":"Aap kis desh se hain?","english":"Which country are you from?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name languages and countries in Hindi and talk about nationality."}}',
'{"items":[{"word":"भाषा","translation":"language","transliteration":"bhaasha","pronunciation":"BHAA-sha","example":"मेरी भाषा।"},{"word":"देश","translation":"country","transliteration":"desh","pronunciation":"desh","example":"मेरा देश।"},{"word":"बोलना","translation":"to speak","transliteration":"bolna","pronunciation":"BOL-na","example":"हिंदी बोलना।"},{"word":"थोड़ा/थोड़ी","translation":"a little (masc/fem)","transliteration":"thoda/thodi","pronunciation":"THO-da/THO-dee","example":"थोड़ी हिंदी।"},{"word":"भारतीय","translation":"Indian","transliteration":"Bhartiya","pronunciation":"bhar-TEE-ya","example":"भारतीय संस्कृति।"},{"word":"किस","translation":"which/what (oblique of कौन)","transliteration":"kis","pronunciation":"kis","example":"किस देश से?"}]}',
'{"title":"आप किस X से हैं? — Which X are you from? (किस = oblique of कौन = which)","pattern":"किस = oblique case of कौन (which/who). Used before postpositions: किस देश से? (which country from?), किस शहर में? (in which city?). Question: आप किस X से हैं? = Which X are you from? Answer: मैं X से हूँ. किस triggers oblique case — the noun after किस may take postpositions.","explanation":"किस (kis) = oblique of कौन (kaun = who/which — interrogative). Used before postpositions: किस + noun + postposition. किस देश से (from which country), किस शहर में (in which city), किस समय (at what time — time question). When asking about a specific instance from a set: कौन = who (no postposition needed) vs. किस = which (before postpositions). कौन सा/कौन सी (kaun sa/kaun si) = which (adjective form before noun without postposition).","examples":[{"sentence":"आप किस शहर में रहते हैं?","transliteration":"Aap kis shahar mein rehte hain?","translation":"In which city do you live?"},{"sentence":"यह किस भाषा में लिखा है?","transliteration":"Yah kis bhaasha mein likha hai?","translation":"In which language is this written?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"भाषा means?","options":["language","country","culture","region"],"correctAnswer":"language"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I speak Hindi and a little English.","options":["मैं हिंदी और थोड़ी अंग्रेज़ी बोलता हूँ।","मैं हिंदी और थोड़ी अंग्रेज़ी बोलती हूँ।","मैं सिर्फ़ हिंदी बोलता हूँ।","मैं हिंदी और अंग्रेज़ी बोलता हूँ।"],"correctAnswer":"मैं हिंदी और थोड़ी अंग्रेज़ी बोलता हूँ।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"आप ___ शहर में रहते हैं?","options":["किस","कौन","क्या","कहाँ"],"correctAnswer":"किस"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In which language is this written?","wordBankItems":["यह","किस","भाषा","में","लिखा","है","?"],"correctAnswer":"यह किस भाषा में लिखा है ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"देश means?","options":["country","city","village","state"],"correctAnswer":"country"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000025',1,'APPROVED','PUBLISHED',
'{"objectives":["Name vegetables and fruits in Hindi at A1","Use weight and quantity expressions","Shop for produce at a market"],"explanation":{"intro":"Vegetables and fruits vocabulary covers common Indian produce and how to buy them at market in Hindi at A1.","culturalNote":"सब्ज़ियाँ और फल — Vegetables and Fruits: सब्ज़ी (sabzi) = vegetable. फल (phal) = fruit. Key vegetables: आलू (aloo = potato), प्याज़ (pyaaz = onion), टमाटर (tamatar = tomato), पालक (palak = spinach), गोभी (gobhi = cauliflower), मटर (matar = peas), बैंगन (baigan = aubergine/brinjal), लहसुन (lahsun = garlic), अदरक (adrak = ginger). Key fruits: आम (aam = mango — king of fruits), केला (kela = banana), अंगूर (angur = grapes), सेब (seb = apple), संतरा (santra = orange), तरबूज़ (tarbuz = watermelon), पपीता (papita = papaya). Spices (मसाले = masale): हल्दी (haldi = turmeric), जीरा (jeera = cumin), धनिया (dhaniya = coriander), मिर्च (mirch = chilli). India is the world''s largest producer of spices. आलू is in almost everything — aloo paratha, aloo sabzi, samosa filling. Sabzi mandi (vegetable wholesale market)."},"examples":[{"hindi":"मुझे एक किलो आलू और आधा किलो प्याज़ चाहिए।","transliteration":"Mujhe ek kilo aloo aur aadha kilo pyaaz chahiye.","english":"I need one kilo of potatoes and half a kilo of onions."},{"hindi":"आम बहुत मीठे हैं।","transliteration":"Aam bahut meethe hain.","english":"The mangoes are very sweet."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name vegetables and fruits in Hindi and shop for produce."}}',
'{"items":[{"word":"आलू","translation":"potato","transliteration":"aloo","pronunciation":"aa-LOO","example":"आलू सब्ज़ी।"},{"word":"प्याज़","translation":"onion","transliteration":"pyaaz","pronunciation":"pyaaz","example":"प्याज़ काटना।"},{"word":"आम","translation":"mango","transliteration":"aam","pronunciation":"aam","example":"मीठा आम।"},{"word":"केला","translation":"banana","transliteration":"kela","pronunciation":"KE-la","example":"पका केला।"},{"word":"किलो","translation":"kilogram","transliteration":"kilo","pronunciation":"KI-lo","example":"एक किलो।"},{"word":"आधा","translation":"half","transliteration":"aadha","pronunciation":"AA-dha","example":"आधा किलो।"}]}',
'{"title":"X किलो Y चाहिए — (I need) X kilos of Y (quantity expression with चाहिए)","pattern":"मुझे X किलो Y चाहिए = I need X kilos of Y. किलो (kilo) = kilogram — invariant (does not change for plural). Quantity + noun: ek kilo aloo = one kilo of potatoes (no ''of'' marker needed — direct juxtaposition). आधा (aadha) = half — follows the same pattern: आधा किलो = half a kilo.","explanation":"Quantity expressions: numeral + unit + commodity (no preposition needed). एक किलो आलू = one kilo of potatoes. दो किलो सेब = two kilos of apples. Units: किलो (kilo), ग्राम (gram), लीटर (litre), पाव (paav = quarter kilo = 250g), आधा (half). Fractions: आधा (aadha = half), पाव (paav = quarter). Note: किलो is invariant — एक किलो, दो किलो (not दो किले). Compare: measurement units in Hindi are generally invariant.","examples":[{"sentence":"मुझे दो लीटर दूध चाहिए।","transliteration":"Mujhe do litre doodh chahiye.","translation":"I need two litres of milk."},{"sentence":"पाव किलो अदरक दीजिए।","transliteration":"Paav kilo adrak dijiye.","translation":"Please give me a quarter kilo of ginger."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"आलू means?","options":["potato","onion","tomato","garlic"],"correctAnswer":"potato"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need one kilo of potatoes and half a kilo of onions.","options":["मुझे एक किलो आलू और आधा किलो प्याज़ चाहिए।","मुझे दो किलो आलू और आधा किलो प्याज़ चाहिए।","मुझे एक किलो आलू और एक किलो प्याज़ चाहिए।","मुझे एक किलो प्याज़ और आधा किलो आलू चाहिए।"],"correctAnswer":"मुझे एक किलो आलू और आधा किलो प्याज़ चाहिए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मुझे दो ___ दूध चाहिए।","options":["लीटर","किलो","ग्राम","पाव"],"correctAnswer":"लीटर"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please give me a quarter kilo of ginger.","wordBankItems":["पाव","किलो","अदरक","दीजिए","।"],"correctAnswer":"पाव किलो अदरक दीजिए ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"आधा means?","options":["half","quarter","double","one"],"correctAnswer":"half"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000026',1,'APPROVED','PUBLISHED',
'{"objectives":["Name everyday objects in Hindi at A1","Use यह/वह with object names","Describe objects by material or function"],"explanation":{"intro":"Everyday objects vocabulary covers common household and personal items and how to describe them in Hindi at A1.","culturalNote":"चीज़ें और वस्तुएँ — Everyday Objects: चीज़ (cheez) = thing (Persian). वस्तु (vastu) = object/item (Sanskrit). Common objects: घड़ी (ghadi = watch/clock), चाबी (chaabi = key), पर्स/बटुआ (purse/batua = purse/wallet), छतरी (chhatri = umbrella), थैला (thaila = bag/sack), शीशा (shesha = mirror/glass), तकिया (takiya = pillow), कंबल (kambal = blanket), टोपी (topi = hat/cap), जूता (joota = shoe). Traditional objects: थाली (thaali = metal plate used for meals), लोटा (lota = metal pot for water — iconic Indian bathroom fixture), दरी (dari = cotton mat). Key: यह/वह with objects (यह = this near, वह = that far). What is it made of: का + material: लकड़ी का (wooden — of wood), लोहे का (of iron), सोने का (of gold), चाँदी का (of silver). Key: भारत में लोहे का स्वामित्व अलग तरह से देखा जाता है (iron ownership viewed differently in India — ironsmiths caste)."},"examples":[{"hindi":"यह चाबी किसकी है?","transliteration":"Yah chaabi kiski hai?","english":"Whose key is this?"},{"hindi":"वह लकड़ी की मेज़ है।","transliteration":"Vah lakdi ki mez hai.","english":"That is a wooden table."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name everyday objects in Hindi and describe what they are made of."}}',
'{"items":[{"word":"घड़ी","translation":"watch/clock","transliteration":"ghadi","pronunciation":"gha-DEE","example":"मेरी घड़ी।"},{"word":"चाबी","translation":"key","transliteration":"chaabi","pronunciation":"CHAA-bee","example":"दरवाज़े की चाबी।"},{"word":"छतरी","translation":"umbrella","transliteration":"chhatri","pronunciation":"CHHATT-ree","example":"बारिश में छतरी।"},{"word":"लकड़ी","translation":"wood","transliteration":"lakdi","pronunciation":"LAK-dee","example":"लकड़ी का फ़र्नीचर।"},{"word":"किसका/किसकी","translation":"whose (masc/fem)","transliteration":"kiska/kiski","pronunciation":"KIS-ka/KIS-ki","example":"यह किसकी है?"},{"word":"टोपी","translation":"hat/cap","transliteration":"topi","pronunciation":"TO-pee","example":"लाल टोपी।"}]}',
'{"title":"यह किसका/किसकी है? — Whose is this? (किसका/किसकी = whose)","pattern":"किसका/किसकी/किसके = whose (interrogative possessive — oblique of किस + का/की/के). किसका = whose (masculine item). किसकी = whose (feminine item). Answer pattern: यह X का/की है = This is X''s. यह मेरी चाबी है (This is my key). Material: Y का/की X = X made of Y. लकड़ी की मेज़ (wooden table — मेज़ is feminine → की).","explanation":"किसका (kiska) = whose (masc.), किसकी (kiski) = whose (fem.), किसके (kiske) = whose (oblique pl.). Agreement with the possessed noun (not the owner). यह किसकी घड़ी है? = Whose watch is this? (घड़ी = feminine → किसकी). यह किसका बैग है? = Whose bag is this? (बैग = masculine → किसका). Answer: यह मेरी घड़ी है (This is my watch). Material construction: Y का/की X — material (Y) + का/की + object (X). लकड़ी (lakdi = wood, feminine) + की + मेज़ = wooden table.","examples":[{"sentence":"यह किसका जूता है?","transliteration":"Yah kiska joota hai?","translation":"Whose shoe is this?"},{"sentence":"वह सोने की अँगूठी है।","transliteration":"Vah sone ki angoothi hai.","translation":"That is a gold ring."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"चाबी means?","options":["key","lock","door","gate"],"correctAnswer":"key"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"That is a wooden table.","options":["वह लकड़ी की मेज़ है।","यह लकड़ी की मेज़ है।","वह लोहे की मेज़ है।","वह लकड़ी का मेज़ है।"],"correctAnswer":"वह लकड़ी की मेज़ है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"यह ___ जूता है?","options":["किसका","किसकी","किसके","किसको"],"correctAnswer":"किसका"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Whose key is this?","wordBankItems":["यह","चाबी","किसकी","है","?"],"correctAnswer":"यह चाबी किसकी है ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"घड़ी means?","options":["watch/clock","key","bag","hat"],"correctAnswer":"watch/clock"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000027',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about music and art in Hindi at A1","Use X सुनना for listening to music","Name musical instruments and art forms"],"explanation":{"intro":"Music and art vocabulary covers Indian classical and popular music, instruments, and art forms in Hindi at A1.","culturalNote":"संगीत और कला — Music and Art: संगीत (sangeet) = music. कला (kala) = art. गाना (gaana) = song/to sing. सुनना (sunna) = to listen. बजाना (bajaana) = to play an instrument. वाद्य यंत्र (vaadya yantra) = musical instrument. Key instruments: सितार (sitar — stringed — Ravi Shankar), तबला (tabla — percussion — rhythmic backbone of classical music), बाँसुरी (bansuri = bamboo flute — associated with Krishna), वीणा (veena — ancient stringed instrument). Indian classical music: Hindustani (North) and Carnatic (South). Raga (राग = raga = melody framework). Taal (ताल = rhythm cycle). बॉलीवुड संगीत (Bollywood music — most popular). A.R. Rahman — Oscar-winning composer. Lata Mangeshkar — most recorded artist. नृत्य (nritya = dance): Bharatanatyam, Kathak, Odissi, Manipuri. Regional: Bhangra (Punjab), Garba (Gujarat). Painting: Madhubani, Warli, Pattachitra. Street art: Mumbai''s Dharavi art project."},"examples":[{"hindi":"मुझे हिंदुस्तानी शास्त्रीय संगीत सुनना बहुत पसंद है।","transliteration":"Mujhe Hindustani shastriya sangeet sunna bahut pasand hai.","english":"I like listening to Hindustani classical music very much."},{"hindi":"वह सितार बजाती है।","transliteration":"Vah sitar bajaati hai.","english":"She plays the sitar."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about music and art in Hindi and name instruments."}}',
'{"items":[{"word":"संगीत","translation":"music","transliteration":"sangeet","pronunciation":"san-GEET","example":"संगीत सुनना।"},{"word":"गाना","translation":"song/to sing","transliteration":"gaana","pronunciation":"GAA-na","example":"गाना गाना।"},{"word":"सितार","translation":"sitar","transliteration":"sitar","pronunciation":"si-TAAR","example":"सितार बजाना।"},{"word":"तबला","translation":"tabla (drums)","transliteration":"tabla","pronunciation":"TAB-la","example":"तबला बजाना।"},{"word":"बजाना","translation":"to play an instrument","transliteration":"bajaana","pronunciation":"ba-JAA-na","example":"सितार बजाना।"},{"word":"शास्त्रीय","translation":"classical","transliteration":"shastriya","pronunciation":"SHAST-ri-ya","example":"शास्त्रीय संगीत।"}]}',
'{"title":"X बजाना — to play instrument X (बजाना = to cause to sound)","pattern":"Instrument + बजाना = to play (an instrument). बजाना = to play/cause to ring/sound (causative of बजना = to ring/sound). Used exclusively for musical instruments. Contrast: खेलना = to play (sports/games — not instruments). सितार बजाना = to play the sitar. तबला बजाना = to play the tabla. Habitual: वह सितार बजाती है = She plays the sitar (bajaati = feminine habitual).","explanation":"बजाना (bajaana) = to play (instrument). Causative: बजना (to ring/sound — intransitive) → बजाना (to make ring/sound — transitive/causative). Only for instruments: वाद्य बजाना. For games/sports: खेलना. For music listening: सुनना. For singing: गाना. Habitual inflection: बजाता है (he plays — masc.), बजाती है (she plays — fem.), बजाते हैं (they play — masc. pl.).","examples":[{"sentence":"मेरे भाई तबला बजाते हैं।","transliteration":"Mere bhai tabla bajaate hain.","translation":"My brother plays the tabla."},{"sentence":"क्या आप कोई वाद्य बजाते हैं?","transliteration":"Kya aap koi vaadya bajaate hain?","translation":"Do you play any instrument?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"संगीत means?","options":["music","dance","art","song"],"correctAnswer":"music"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"She plays the sitar.","options":["वह सितार बजाती है।","वह सितार बजाता है।","वह तबला बजाती है।","वह सितार सुनती है।"],"correctAnswer":"वह सितार बजाती है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मेरे भाई तबला ___ हैं।","options":["बजाते","बजाती","बजाता","बजाना"],"correctAnswer":"बजाते"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Do you play any instrument?","wordBankItems":["क्या","आप","कोई","वाद्य","बजाते","हैं","?"],"correctAnswer":"क्या आप कोई वाद्य बजाते हैं ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"बजाना means?","options":["to play an instrument","to sing","to listen","to dance"],"correctAnswer":"to play an instrument"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000028',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about the environment in Hindi at A1","Use X बचाना for protecting the environment","Discuss basic environmental issues"],"explanation":{"intro":"Environment vocabulary covers nature, pollution, and conservation with basic environmental action phrases in Hindi at A1.","culturalNote":"पर्यावरण — Environment: पर्यावरण (paryavaran) = environment (pari = around + avarana = covering — Sanskrit). प्रदूषण (pradushan = pollution — pra = very + dushan = corruption). वायु प्रदूषण (vayu pradushan = air pollution). जल प्रदूषण (jal pradushan = water pollution). पेड़ लगाना (ped lagana = to plant trees). बचाना (bachaana = to save/protect). साफ़ करना (saaf karna = to clean). India has major environmental challenges: Delhi air quality (AQI often 400+), Ganga river pollution, plastic waste. But also: India was a pioneer in tiger conservation (Project Tiger 1973), India receives significant carbon credits for its forests, India''s solar energy is one of the world''s largest programs. Chipko Movement (1973 — Uttarakhand — women hugged trees to prevent logging — pioneering environmental movement). Bishnoi community (Rajasthan — protected trees and wildlife for 500 years). Key: भविष्य के लिए (bhavishya ke liye = for the future). पृथ्वी (prithvi = earth). नदी माँ (nadi maa = mother river — Ganga, Yamuna)."},"examples":[{"hindi":"हमें पर्यावरण बचाना चाहिए।","transliteration":"Hamein paryavaran bachaana chahiye.","english":"We should protect the environment."},{"hindi":"प्रदूषण कम करना ज़रूरी है।","transliteration":"Pradushan kam karna zaroori hai.","english":"It is necessary to reduce pollution."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about the environment and basic conservation in Hindi."}}',
'{"items":[{"word":"पर्यावरण","translation":"environment","transliteration":"paryavaran","pronunciation":"par-ya-VA-ran","example":"पर्यावरण की रक्षा।"},{"word":"प्रदूषण","translation":"pollution","transliteration":"pradushan","pronunciation":"pra-DOO-shan","example":"वायु प्रदूषण।"},{"word":"बचाना","translation":"to save/protect","transliteration":"bachaana","pronunciation":"ba-CHAA-na","example":"पर्यावरण बचाना।"},{"word":"ज़रूरी","translation":"necessary","transliteration":"zaroori","pronunciation":"za-ROO-ree","example":"ज़रूरी है।"},{"word":"कम करना","translation":"to reduce","transliteration":"kam karna","pronunciation":"kam KAR-na","example":"प्रदूषण कम करना।"},{"word":"पेड़ लगाना","translation":"to plant trees","transliteration":"ped lagana","pronunciation":"ped la-GAA-na","example":"पेड़ लगाना।"}]}',
'{"title":"हमें X करना चाहिए — We should do X (चाहिए for moral obligation)","pattern":"हमें X करना चाहिए = We should do X. हमें = to us (dative — oblique of हम). X करना = doing X (infinitive as direct object). चाहिए = should/ought to (impersonal modal — does not conjugate). Used for: moral obligation, advice, recommendations. Compare: हमें X करना है (we need/have to do X — stronger necessity). हमें X करना पड़ता है (we have to do X — compulsion).","explanation":"चाहिए with obligation: हमें/मुझे/आपको + infinitive + चाहिए = should/ought to. Moral/social obligation: हमें पर्यावरण बचाना चाहिए = We should protect the environment. Advice: आपको डॉक्टर से मिलना चाहिए = You should see a doctor. Strength of obligation: चाहिए (should — advisory), करना है (need to — intention/plan), करना पड़ता है (have to — external compulsion), करना होगा (will have to — future obligation). X करना चाहिए = should do X (generic): पानी बचाना चाहिए = water should be saved.","examples":[{"sentence":"आपको अधिक पानी पीना चाहिए।","transliteration":"Aapko adhik paani peena chahiye.","translation":"You should drink more water."},{"sentence":"हमें कचरा नहीं फेंकना चाहिए।","transliteration":"Hamein kachra nahi phenkna chahiye.","translation":"We should not throw rubbish."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"प्रदूषण means?","options":["pollution","environment","forest","water"],"correctAnswer":"pollution"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We should protect the environment.","options":["हमें पर्यावरण बचाना चाहिए।","हमें प्रदूषण बचाना चाहिए।","मुझे पर्यावरण बचाना चाहिए।","हमें पर्यावरण बचाना है।"],"correctAnswer":"हमें पर्यावरण बचाना चाहिए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"आपको अधिक पानी पीना ___ ।","options":["चाहिए","है","होगा","पड़ता है"],"correctAnswer":"चाहिए"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We should not throw rubbish.","wordBankItems":["हमें","कचरा","नहीं","फेंकना","चाहिए","।"],"correctAnswer":"हमें कचरा नहीं फेंकना चाहिए ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"बचाना means?","options":["to save/protect","to reduce","to clean","to plant"],"correctAnswer":"to save/protect"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

